+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * imported sales sold in those days, actual use from every consume movement.
+ * Items where either is above zero; difference is actual minus theoretical.
+ */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must not be after to" });
+  const theoretical = new Map();
+  for (const sale of store.data.sales) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === sale.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, sale.qty)) theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+  }
+  const actual = new Map();
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId !== undefined) actual.set(itemId, (actual.get(itemId) ?? 0) + m.qty);
+  }
+  const r3 = (x) => Math.round(x * 1000) / 1000;
+  return listItems(store)
+    .map((item) => {
+      const t = r3(theoretical.get(item.id) ?? 0);
+      const a = r3(actual.get(item.id) ?? 0);
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: r3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
